begin;
create table if not exists public.mme_finance_accounts(account_id uuid primary key default gen_random_uuid(),account_code text not null unique,account_name text not null,account_type text not null check(account_type in ('asset','liability','equity','revenue','expense')),parent_account_id uuid references public.mme_finance_accounts(account_id),is_active boolean not null default true,created_by_auth_user_id uuid not null,created_at timestamptz not null default now());
create table if not exists public.mme_finance_journal_entries(journal_id uuid primary key default gen_random_uuid(),entry_date date not null,description text not null,status text not null default 'draft' check(status in ('draft','posted','void')),source_reference text,created_by_auth_user_id uuid not null,posted_by_auth_user_id uuid,posted_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.mme_finance_journal_lines(line_id uuid primary key default gen_random_uuid(),journal_id uuid not null references public.mme_finance_journal_entries(journal_id) on delete cascade,account_id uuid not null references public.mme_finance_accounts(account_id),debit numeric(14,2) not null default 0 check(debit>=0),credit numeric(14,2) not null default 0 check(credit>=0),memo text,check(not(debit>0 and credit>0)),check(debit+credit>0));
create table if not exists public.mme_finance_payables(payable_id uuid primary key default gen_random_uuid(),vendor_name text not null,invoice_reference text not null,invoice_date date not null,due_date date,amount numeric(14,2) not null check(amount>0),currency char(3) not null default 'USD',status text not null default 'open' check(status in ('open','approved','scheduled','paid','void')),description text,created_by_auth_user_id uuid not null,approved_by_auth_user_id uuid,created_at timestamptz not null default now(),unique(vendor_name,invoice_reference));
create table if not exists public.mme_finance_receivables(receivable_id uuid primary key default gen_random_uuid(),customer_reference text not null,invoice_reference text not null unique,invoice_date date not null,due_date date,amount numeric(14,2) not null check(amount>0),currency char(3) not null default 'USD',status text not null default 'open' check(status in ('open','partially_paid','paid','void')),description text,created_by_auth_user_id uuid not null,created_at timestamptz not null default now());
create table if not exists public.mme_finance_receivable_payments(payment_id uuid primary key default gen_random_uuid(),receivable_id uuid not null references public.mme_finance_receivables(receivable_id),amount numeric(14,2) not null check(amount>0),payment_reference text not null,received_at timestamptz not null default now(),recorded_by_auth_user_id uuid not null,unique(payment_reference));
create table if not exists public.mme_finance_bank_accounts(bank_account_id uuid primary key default gen_random_uuid(),institution_name text not null,account_label text not null,masked_account_reference text, currency char(3) not null default 'USD',is_active boolean not null default true,created_by_auth_user_id uuid not null,created_at timestamptz not null default now());
create table if not exists public.mme_finance_bank_reconciliations(reconciliation_id uuid primary key default gen_random_uuid(),bank_account_id uuid not null references public.mme_finance_bank_accounts(bank_account_id),statement_start date not null,statement_end date not null,statement_ending_balance numeric(14,2) not null,ledger_ending_balance numeric(14,2) not null,difference numeric(14,2) generated always as (statement_ending_balance-ledger_ending_balance) stored,status text not null default 'draft' check(status in ('draft','review','reconciled','exception')),statement_reference text,prepared_by_auth_user_id uuid not null,reviewed_by_auth_user_id uuid,reviewed_at timestamptz,created_at timestamptz not null default now(),check(statement_end>=statement_start));
create table if not exists public.mme_finance_sales_tax_records(tax_record_id uuid primary key default gen_random_uuid(),period_start date not null,period_end date not null,jurisdiction text not null,taxable_sales numeric(14,2) not null default 0,tax_collected numeric(14,2) not null default 0,exempt_sales numeric(14,2) not null default 0,status text not null default 'draft' check(status in ('draft','review','filed','paid')),source_reference text,created_by_auth_user_id uuid not null,created_at timestamptz not null default now(),check(period_end>=period_start),check(taxable_sales>=0 and tax_collected>=0 and exempt_sales>=0));
create table if not exists public.mme_finance_audit(audit_id bigint generated always as identity primary key,actor_auth_user_id uuid not null,actor_role text not null,action text not null,entity_type text not null,entity_id uuid,details jsonb not null default '{}',request_id uuid not null,created_at timestamptz not null default now());
create index if not exists mme_finance_journal_date_idx on public.mme_finance_journal_entries(entry_date desc,status);
create index if not exists mme_finance_ap_due_idx on public.mme_finance_payables(due_date,status);
create index if not exists mme_finance_ar_due_idx on public.mme_finance_receivables(due_date,status);
create index if not exists mme_finance_reconciliation_idx on public.mme_finance_bank_reconciliations(bank_account_id,statement_end desc);
create index if not exists mme_finance_tax_period_idx on public.mme_finance_sales_tax_records(period_start,period_end,jurisdiction);
alter table public.mme_finance_accounts enable row level security;alter table public.mme_finance_journal_entries enable row level security;alter table public.mme_finance_journal_lines enable row level security;alter table public.mme_finance_payables enable row level security;alter table public.mme_finance_receivables enable row level security;alter table public.mme_finance_receivable_payments enable row level security;alter table public.mme_finance_bank_accounts enable row level security;alter table public.mme_finance_bank_reconciliations enable row level security;alter table public.mme_finance_sales_tax_records enable row level security;alter table public.mme_finance_audit enable row level security;
do $$ declare t text; begin foreach t in array array['mme_finance_accounts','mme_finance_journal_entries','mme_finance_journal_lines','mme_finance_payables','mme_finance_receivables','mme_finance_receivable_payments','mme_finance_bank_accounts','mme_finance_bank_reconciliations','mme_finance_sales_tax_records','mme_finance_audit'] loop execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end $$;
grant usage,select on sequence public.mme_finance_audit_audit_id_seq to service_role;
comment on table public.mme_finance_journal_entries is 'Accounting journal ledger. Posting requires balanced debit and credit lines; this ledger does not move funds.';
comment on table public.mme_finance_bank_reconciliations is 'Statement reconciliation worksheet; statement balances require independently verified bank source data.';
comment on table public.mme_finance_sales_tax_records is 'Sales tax reporting staging; does not file returns or remit tax.';
commit;
